INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist situationsgerechte Kommunikation ein wichtiger Aspekt der Kundenkommunikation?', 2, '[{"text": "Ja", "correct": true, "because": "Passt sich an Kontext an"}, {"text": "Nein", "correct": false, "because": "Sie ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die situationsgerechte Kommunikation?', 3, '[{"text": "Effektive und passende Kundeninteraktion", "correct": true, "because": "Fördert Verständnis"}, {"text": "Projektziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Situationsgerechte Kommunikation berücksichtigt den Kontext. b) Sie ist immer gleich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen situationsgerechte Kommunikation?', 4, '[{"text": "Kundentyp", "correct": true, "because": "Beeinflusst Ton"}, {"text": "Unklare Botschaften", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Projektphase", "correct": true, "because": "Bestimmt Inhalt"}, {"text": "Kommunikationskanal", "correct": true, "because": "Passt Medium an"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Kundenkommunikation ohne Situationsanpassung effektiv sein?', 2, '[{"text": "Nein", "correct": true, "because": "Missverständnisse drohen"}, {"text": "Ja", "correct": false, "because": "Weniger effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt situationsgerechte Kommunikation?', 3, '[{"text": "Kundenbedürfnisse gezielt ansprechen", "correct": true, "because": "Fördert Zufriedenheit"}, {"text": "Team intern einteilen", "correct": false, "because": "Projektleiteraufgabe"}, {"text": "Projekt neu finanzieren", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist situationsgerechte Kommunikation nur für technische Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Projekte"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe gehört zur situationsgerechten Kommunikation?', 3, '[{"text": "Kunden je nach Phase informieren", "correct": true, "because": "Passt Inhalt an"}, {"text": "Zeitplan neu erstellen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Kosten neu kalkulieren", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Situationsgerechte Kommunikation fördert Vertrauen. b) Sie ignoriert den Kunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, kundenorientiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne situationsgerechte Kommunikation?', 3, '[{"text": "Missverständnisse mit Kunden", "correct": true, "because": "Fehlende Anpassung"}, {"text": "Kommunikation wird schneller", "correct": false, "because": "Eher Verwirrung"}, {"text": "Kunden sind zufriedener", "correct": false, "because": "Unzufriedenheit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann situationsgerechte Kommunikation ohne Kontext erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Kontext ist Basis"}, {"text": "Ja", "correct": false, "because": "Unpassend unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt situationsgerechte Kommunikation?', 3, '[{"text": "Technische Details für IT-Kunden", "correct": true, "because": "Konkret und angepasst"}, {"text": "Immer gleiche Nachricht", "correct": false, "because": "Nicht situationsgerecht"}, {"text": "Kunden ignorieren", "correct": false, "because": "Keine Kommunikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist situationsgerechte Kommunikation nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team kommuniziert auch"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei situationsgerechter Kommunikation wichtig?', 4, '[{"text": "Kundenbedürfnisse", "correct": true, "because": "Bestimmen Inhalt"}, {"text": "Unklare Sprache", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Ton und Stil", "correct": true, "because": "Passen Ansprache"}, {"text": "Situationsanalyse", "correct": true, "because": "Legt Ansatz fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss situationsgerechte Kommunikation dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis und Klarheit"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt situationsgerechte Kommunikation?', 3, '[{"text": "E-Mail mit angepasstem Ton", "correct": true, "because": "Flexibel einsetzbar"}, {"text": "Keine Anpassung", "correct": false, "because": "Fehlt Flexibilität"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann situationsgerechte Kommunikation ohne Kundenfeedback erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Feedback steuert Anpassung"}, {"text": "Ja", "correct": false, "because": "Uninformiert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert situationsgerechte Kommunikation?', 3, '[{"text": "Unklare Kundenbedürfnisse", "correct": true, "because": "Verhindern Anpassung"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Ablauf"}, {"text": "Gute Kommunikationswege", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Situationsgerechte Kommunikation steigert Kundenzufriedenheit. b) Sie ist nur für technische Kunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der situationsgerechten Kommunikation?', 3, '[{"text": "Bessere Kundenbindung", "correct": true, "because": "Fördert Vertrauen"}, {"text": "Maximale Verwirrung", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Anpassung", "correct": false, "because": "Fördert Verständnis"}]');
